using System.Security.Cryptography;using System.Text;using Microsoft.EntityFrameworkCore;using WanderXServer.BusinessObject;using WanderXServer.BusinessObject.Enums;using WanderXServer.DataAccessLayer;using WanderXServer.Dtos.Account;
namespace WanderXServer.Services;
public sealed class AccountManagementService{
 private readonly WanderXDbContext _db;private readonly ISmsSender _sms;private readonly IConfiguration _cfg;public AccountManagementService(WanderXDbContext db,ISmsSender sms,IConfiguration cfg){_db=db;_sms=sms;_cfg=cfg;}
 public async Task<AdminUserPage> List(AdminUserQuery q){var x=_db.Users.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(q.Keyword)){var k=q.Keyword.Trim();x=x.Where(u=>u.FullName.Contains(k)||u.Email.Contains(k)||u.PhoneNumber.Contains(k));}if(q.Role.HasValue)x=x.Where(u=>u.Role==q.Role);if(q.PhoneVerified.HasValue)x=x.Where(u=>u.IsPhoneConfirmed==q.PhoneVerified);if(!string.IsNullOrWhiteSpace(q.Status)){if(q.Status.Equals("Locked",StringComparison.OrdinalIgnoreCase))x=x.Where(u=>u.AccountStatus=="Locked"&&(!u.LockoutEnd.HasValue||u.LockoutEnd>DateTime.UtcNow));else x=x.Where(u=>u.AccountStatus==q.Status);}var total=await x.CountAsync();var rows=await x.OrderBy(u=>u.FullName).ThenBy(u=>u.Id).Skip((q.Page-1)*q.PageSize).Take(q.PageSize).ToListAsync();return new(){Page=q.Page,PageSize=q.PageSize,TotalCount=total,Items=rows.Select(Map).ToList()};}
 public async Task<AdminUserDetail> Detail(Guid id){var u=await _db.Users.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id)??throw new KeyNotFoundException("USER_NOT_FOUND");var logs=await _db.AccountAuditLogs.AsNoTracking().Where(x=>x.TargetUserId==id).OrderByDescending(x=>x.CreatedAt).Take(100).ToListAsync();var r=new AdminUserDetail{Id=u.Id,FullName=u.FullName,Email=u.Email,PhoneNumber=u.PhoneNumber,Role=u.Role.ToString(),Status=EffectiveStatus(u),PhoneVerified=u.IsPhoneConfirmed,CreatedAt=u.CreatedAt,LastLoginAt=u.LastLoginAt,LockoutEnd=u.LockoutEnd,Permissions=Permissions(u.Role),AuditLogs=logs.Select(x=>new AccountAuditItem{Id=x.Id,Action=x.Action,OldValue=x.OldValue,NewValue=x.NewValue,Reason=x.Reason,CreatedAt=x.CreatedAt,ActorUserId=x.ActorUserId}).ToList()};return r;}
 public async Task<AdminUserDetail> ChangeRole(Guid actor,Guid id,ChangeRoleRequest req){if(!Enum.TryParse<UserRole>(req.Role,true,out var role))throw new ArgumentException("INVALID_ROLE");await using var tx=await _db.Database.BeginTransactionAsync();var u=await _db.Users.FirstOrDefaultAsync(x=>x.Id==id)??throw new KeyNotFoundException("USER_NOT_FOUND");if(u.Role==UserRole.Admin&&role!=UserRole.Admin&&await _db.Users.CountAsync(x=>x.Role==UserRole.Admin)==1)throw new InvalidOperationException("LAST_ADMIN_PROTECTED");if(role==UserRole.Guide&&!await _db.GuideProfiles.AnyAsync(x=>x.UserId==id))throw new InvalidOperationException("ROLE_PREREQUISITE_MISSING");var old=u.Role.ToString();u.Role=role;u.TokenVersion++;u.UpdatedAt=DateTime.UtcNow;Audit(actor,id,"ROLE_CHANGED",old,role.ToString(),req.Reason);await _db.SaveChangesAsync();await tx.CommitAsync();return await Detail(id);}
 public async Task<AdminUserDetail> Lock(Guid actor,Guid id,LockUserRequest req){if(actor==id)throw new InvalidOperationException("SELF_LOCK_FORBIDDEN");await using var tx=await _db.Database.BeginTransactionAsync();var u=await _db.Users.FirstOrDefaultAsync(x=>x.Id==id)??throw new KeyNotFoundException("USER_NOT_FOUND");if(EffectiveStatus(u)=="Locked")throw new InvalidOperationException("USER_ALREADY_LOCKED");if(u.Role==UserRole.Admin&&await _db.Users.CountAsync(x=>x.Role==UserRole.Admin)==1)throw new InvalidOperationException("LAST_ADMIN_PROTECTED");if(req.LockUntil.HasValue&&req.LockUntil<=DateTime.UtcNow)throw new ArgumentException("LOCK_UNTIL_INVALID");u.AccountStatus="Locked";u.LockoutEnd=req.LockUntil;u.LockReason=req.Reason;u.TokenVersion++;u.UpdatedAt=DateTime.UtcNow;Audit(actor,id,"LOCKED","Active",req.LockUntil?.ToString("O")??"Indefinite",req.Reason);await _db.SaveChangesAsync();await tx.CommitAsync();return await Detail(id);}
 public async Task<AdminUserDetail> Unlock(Guid actor,Guid id,UnlockUserRequest req){await using var tx=await _db.Database.BeginTransactionAsync();var u=await _db.Users.FirstOrDefaultAsync(x=>x.Id==id)??throw new KeyNotFoundException("USER_NOT_FOUND");u.AccountStatus="Active";u.LockoutEnd=null;u.LockReason=null;u.TokenVersion++;u.UpdatedAt=DateTime.UtcNow;Audit(actor,id,"UNLOCKED","Locked","Active",req.Reason);await _db.SaveChangesAsync();await tx.CommitAsync();return await Detail(id);}
 public async Task<SendPhoneOtpResponse> SendOtp(Guid userId,SendPhoneOtpRequest req){var phone=NormalizePhone(req.PhoneNumber);var u=await _db.Users.FirstOrDefaultAsync(x=>x.Id==userId)??throw new KeyNotFoundException("USER_NOT_FOUND");if(await _db.Users.AnyAsync(x=>x.Id!=userId&&x.PhoneNumber==phone))throw new InvalidOperationException("PHONE_ALREADY_USED");var now=DateTime.UtcNow;var last=await _db.PhoneVerifications.Where(x=>x.UserId==userId&&x.PhoneNumber==phone).OrderByDescending(x=>x.CreatedAt).FirstOrDefaultAsync();var cooldown=_cfg.GetValue("PhoneOtp:ResendCooldownSeconds",60);if(last!=null&&(now-last.LastSentAt).TotalSeconds<cooldown)throw new InvalidOperationException("OTP_COOLDOWN");foreach(var old in await _db.PhoneVerifications.Where(x=>x.UserId==userId&&x.Status=="Pending").ToListAsync())old.Status="Expired";var id=Guid.NewGuid();var otp=RandomNumberGenerator.GetInt32(0,1_000_000).ToString("D6");var expires=now.AddMinutes(_cfg.GetValue("PhoneOtp:ExpiryMinutes",5));var row=new PhoneVerification{Id=id,UserId=userId,PhoneNumber=phone,OtpHash=Hash(id,otp),ExpiresAt=expires,MaxAttempts=_cfg.GetValue("PhoneOtp:MaxAttempts",5),LastSentAt=now,CreatedAt=now};_db.PhoneVerifications.Add(row);await _db.SaveChangesAsync();try{row.ProviderMessageId=await _sms.SendAsync(phone,$"WanderX verification code: {otp}. It expires in 5 minutes.");await _db.SaveChangesAsync();}catch{row.Status="Failed";await _db.SaveChangesAsync();throw new InvalidOperationException("SMS_PROVIDER_ERROR");}return new(){VerificationId=id,MaskedPhone=Mask(phone),ExpiresAt=expires,ResendAfterSeconds=cooldown};}
 public async Task VerifyOtp(Guid userId,VerifyPhoneOtpRequest req){await using var tx=await _db.Database.BeginTransactionAsync();var row=await _db.PhoneVerifications.FirstOrDefaultAsync(x=>x.Id==req.VerificationId&&x.UserId==userId)??throw new InvalidOperationException("OTP_INVALID");var now=DateTime.UtcNow;if(row.Status!="Pending")throw new InvalidOperationException(row.Status=="Locked"?"OTP_MAX_ATTEMPTS":"OTP_INVALID");if(row.ExpiresAt<now){row.Status="Expired";await _db.SaveChangesAsync();throw new InvalidOperationException("OTP_EXPIRED");}var actual=Convert.FromHexString(Hash(row.Id,req.Otp));var expected=Convert.FromHexString(row.OtpHash);if(!CryptographicOperations.FixedTimeEquals(actual,expected)){row.AttemptCount++;if(row.AttemptCount>=row.MaxAttempts)row.Status="Locked";await _db.SaveChangesAsync();throw new InvalidOperationException(row.Status=="Locked"?"OTP_MAX_ATTEMPTS":"OTP_INVALID");}var u=await _db.Users.FirstAsync(x=>x.Id==userId);u.PhoneNumber=row.PhoneNumber;u.IsPhoneConfirmed=true;u.UpdatedAt=now;row.Status="Verified";row.VerifiedAt=now;foreach(var other in await _db.PhoneVerifications.Where(x=>x.UserId==userId&&x.Id!=row.Id&&x.Status=="Pending").ToListAsync())other.Status="Expired";Audit(userId,userId,"PHONE_VERIFIED",null,Mask(row.PhoneNumber),"OTP verified");await _db.SaveChangesAsync();await tx.CommitAsync();}
 private void Audit(Guid actor,Guid target,string action,string? oldValue,string? newValue,string reason)=>_db.AccountAuditLogs.Add(new(){ActorUserId=actor,TargetUserId=target,Action=action,OldValue=oldValue,NewValue=newValue,Reason=reason});private string Hash(Guid id,string otp){var secret=_cfg["PhoneOtp:HashSecret"]??_cfg["Jwt:Key"]??"WanderX-development-secret";return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes($"{id:N}:{otp}:{secret}")));}private static string NormalizePhone(string p){var x=new string(p.Where(c=>char.IsDigit(c)||c=='+').ToArray());if(x.StartsWith("0"))x="+84"+x[1..];if(!x.StartsWith("+")||x.Length<10||x.Length>16)throw new ArgumentException("PHONE_INVALID");return x;}private static string Mask(string p)=>p.Length<7?p:$"{p[..3]}****{p[^3..]}";private static string EffectiveStatus(ApplicationUser u)=>u.AccountStatus=="Locked"&&(!u.LockoutEnd.HasValue||u.LockoutEnd>DateTime.UtcNow)?"Locked":u.AccountStatus=="Inactive"?"Inactive":"Active";private static AdminUserItem Map(ApplicationUser u)=>new(){Id=u.Id,FullName=u.FullName,Email=u.Email,PhoneNumber=u.PhoneNumber,Role=u.Role.ToString(),Status=EffectiveStatus(u),PhoneVerified=u.IsPhoneConfirmed,CreatedAt=u.CreatedAt,LastLoginAt=u.LastLoginAt,LockoutEnd=u.LockoutEnd};public static List<string> Permissions(UserRole r)=>r switch{UserRole.Admin=>new(){"USER_MANAGE","ROLE_ASSIGN","USER_LOCK","DASHBOARD_VIEW","SYSTEM_CONFIG"},UserRole.Staff=>new(){"DASHBOARD_VIEW"},UserRole.Guide=>new(){"GUIDE_PORTAL_VIEW","GUIDE_SELF_EDIT","ASSIGNMENT_VIEW"},_=>new(){"QUIZ_TAKE","RECOMMENDATION_VIEW","PROFILE_SELF_VIEW","PROFILE_SELF_EDIT"}};
}